  /* deleteMasterMdAmCommonManage */
		 DELETE FROM  ICOMCOD1
		WHERE TYPE='M000'
		AND CODE = #{CODE}

 /*updateMasterMdAmCommonManageDetail*/
		UPDATE ICOMCOD1					
		SET TEXT1 = #{TEXT1_DETAIL},
			TEXT2 = #{TEXT2_DETAIL},
			TEXT3 = #{TEXT3_DETAIL},
			TEXT4 = #{TEXT4_DETAIL},
			FLAG = #{FLAG_DETAIL},
			VALUE1 = DECODE(#{VALUE1_DETAIL}, '', 0 ,#{VALUE1_DETAIL})
		WHERE TYPE = #{TYPE_DETAIL}
		   AND CODE = #{CODE_DETAIL}

  /* deleteMasterMdAmCommonManageDetail */
		 DELETE FROM  ICOMCOD1
		WHERE TYPE=#{TYPE_DETAIL}
		AND CODE = #{CODE_DETAIL}
